public class InnerWorkspaceWorkspaceThemePaletteFactory(Action<Humidifier.Connect.WorkspaceTypes.WorkspaceThemePalette> factoryAction = null) : SubResourceFactory<Humidifier.Connect.WorkspaceTypes.WorkspaceThemePalette>
{

    internal InnerWorkspacePaletteNavigationFactory NavigationFactory { get; set; }

    internal InnerWorkspacePaletteHeaderFactory HeaderFactory { get; set; }

    internal InnerWorkspacePaletteCanvasFactory CanvasFactory { get; set; }

    internal InnerWorkspacePalettePrimaryFactory PrimaryFactory { get; set; }

    protected override Humidifier.Connect.WorkspaceTypes.WorkspaceThemePalette Create()
    {
        var workspaceThemePaletteResult = CreateWorkspaceThemePalette();
        factoryAction?.Invoke(workspaceThemePaletteResult);

        return workspaceThemePaletteResult;
    }

    private Humidifier.Connect.WorkspaceTypes.WorkspaceThemePalette CreateWorkspaceThemePalette()
    {
        var workspaceThemePaletteResult = new Humidifier.Connect.WorkspaceTypes.WorkspaceThemePalette();

        return workspaceThemePaletteResult;
    }
    public override void CreateChildren(Humidifier.Connect.WorkspaceTypes.WorkspaceThemePalette result)
    {
        base.CreateChildren(result);

        result.Navigation ??= NavigationFactory?.Build();
        result.Header ??= HeaderFactory?.Build();
        result.Canvas ??= CanvasFactory?.Build();
        result.Primary ??= PrimaryFactory?.Build();
    }

} // End Of Class

